import java.io.DataInputStream

class FastReader(stream: java.io.InputStream) {
    private val BUFSZ = 1 shl 16
    private val din = DataInputStream(stream)
    private val buffer = ByteArray(BUFSZ)
    private var bufferPointer = 0
    private var bytesRead = 0

    private fun read(): Byte {
        if (bufferPointer == bytesRead) fillBuffer()
        return buffer[bufferPointer++]
    }

    private fun fillBuffer() {
        bytesRead = din.read(buffer, 0, BUFSZ)
        bufferPointer = 0
        if (bytesRead == -1) { bytesRead = 0; buffer[0] = -1 }
    }

    fun nextInt(): Int {
        var ret = 0
        var b = read()
        while (b <= ' '.code.toByte()) b = read()
        val neg = b == '-'.code.toByte()
        if (neg) b = read()
        while (b >= '0'.code.toByte() && b <= '9'.code.toByte()) {
            ret = ret * 10 + (b - '0'.code.toByte())
            b = read()
        }
        return if (neg) -ret else ret
    }
}

class BIT(val n: Int) {
    val tree = IntArray(n + 1)
    fun update(pos: Int, v: Int) {
        var i = pos
        while (i <= n) {
            if (tree[i] < v) tree[i] = v
            i += i and (-i)
        }
    }
    fun query(pos: Int): Int {
        var i = pos
        var res = 0
        while (i > 0) {
            if (tree[i] > res) res = tree[i]
            i -= i and (-i)
        }
        return res
    }
    fun clear() {
        java.util.Arrays.fill(tree, 0)
    }
}

fun main() {
    val fr = FastReader(System.`in`)
    val n = fr.nextInt()
    val m = fr.nextInt()
    val diff = IntArray(m + 2)
    for (i in 0 until n) {
        val l = fr.nextInt()
        val r = fr.nextInt()
        diff[l]++
        diff[r + 1]--
    }
    val a = IntArray(m + 1)
    var cur = 0
    for (i in 1..m) {
        cur += diff[i]
        a[i] = cur
    }
    val size = n + 2
    val bit = BIT(size)
    val f = IntArray(m + 2)
    val g = IntArray(m + 2)
    for (i in 1..m) {
        val q = bit.query(a[i] + 1)
        f[i] = q + 1
        bit.update(a[i] + 1, f[i])
    }
    bit.clear()
    for (i in m downTo 1) {
        val q = bit.query(a[i] + 1)
        g[i] = q + 1
        bit.update(a[i] + 1, g[i])
    }
    var ans = 0
    for (i in 1..m) {
        val v = f[i] + g[i] - 1
        if (v > ans) ans = v
    }
    println(ans)
}
