import java.io.DataInputStream

class FastReader(stream: java.io.InputStream) {
    private val BUFSZ = 1 shl 16
    private val din = DataInputStream(stream)
    private val buffer = ByteArray(BUFSZ)
    private var bufferPointer = 0
    private var bytesRead = 0

    private fun read(): Byte {
        if (bufferPointer == bytesRead) fillBuffer()
        return buffer[bufferPointer++]
    }

    private fun fillBuffer() {
        bytesRead = din.read(buffer, 0, BUFSZ)
        bufferPointer = 0
        if (bytesRead == -1) { bytesRead = 0; buffer[0] = -1 }
    }

    fun nextInt(): Int {
        var ret = 0
        var b = read()
        while (b <= ' '.code.toByte()) b = read()
        val neg = b == '-'.code.toByte()
        if (neg) b = read()
        while (b >= '0'.code.toByte() && b <= '9'.code.toByte()) {
            ret = ret * 10 + (b - '0'.code.toByte())
            b = read()
        }
        return if (neg) -ret else ret
    }
}

fun main() {
    val MOD = 1_000_000_007L
    val fr = FastReader(System.`in`)
    val n = fr.nextInt()
    val k = fr.nextInt()

    val sz = maxOf(n + 1, 2)
    val inv = LongArray(sz)
    inv[1] = 1L
    for (i in 2..n) {
        inv[i] = (MOD - (MOD / i) * inv[(MOD % i).toInt()] % MOD) % MOD
    }

    // pre[i] = A(0)+...+A(i-1)
    val pre = LongArray(n + 1)
    pre[0] = 0L
    if (n >= 1) pre[1] = 1L  // A(0) = 1

    for (m in 1 until n) {
        val lo = if (m - k > 0) m - k else 0
        var s = pre[m] - pre[lo]
        s %= MOD
        if (s < 0) s += MOD
        val a = inv[m] * s % MOD
        pre[m + 1] = (pre[m] + a) % MOD
    }

    val total = pre[n]

    // (n-1)! and n!
    var factNm1 = 1L
    for (i in 1..(n - 1)) {
        factNm1 = factNm1 * i % MOD
    }
    val factN = factNm1 * n % MOD

    val good = factNm1 * total % MOD
    var ans = (factN - good) % MOD
    if (ans < 0) ans += MOD
    println(ans)
}
