import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readText())
    val x = st.nextToken().toLong()
    val y = st.nextToken().toLong()
    val l = st.nextToken().toLong()
    val r = st.nextToken().toLong()

    fun powers(base: Long, lim: Long): List<Long> {
        val res = ArrayList<Long>()
        var p = 1L
        while (true) {
            res.add(p)
            if (p > lim / base) break
            p *= base
        }
        return res
    }

    val px = powers(x, r)
    val py = powers(y, r)

    val list = ArrayList<Long>()
    for (a in px) {
        for (b in py) {
            if (a > r - b) continue
            val s = a + b
            if (s in l..r) list.add(s)
        }
    }
    list.sort()

    var ans = 0L
    var prev = l - 1
    for (u in list) {
        if (u - prev - 1 > ans) ans = u - prev - 1
        prev = u
    }
    if (r - prev > ans) ans = r - prev
    println(ans)
}
