    val h = n / 2
    val first = LongArray(h) { a[it] }
    val second = LongArray(n - h) { a[h + it] }
    val s1 = gen(first, m)
    val s2 = gen(second, m)
    s2.sort()
    val maxSecond = s2[s2.size - 1]
    var ans = 0L
    for (x in s1) {
        // find largest y <= m-1-x
        val target = m - 1 - x
        var lo = 0
        var hi = s2.size - 1
        var idx = -1
        while (lo <= hi) {
            val mid = (lo + hi) / 2
            if (s2[mid] <= target) {
                idx = mid
                lo = mid + 1
            } else {
                hi = mid - 1
            }
        }
        if (idx >= 0) {
            val v = x + s2[idx]
            if (v > ans) ans = v
        }
        val v2 = (x + maxSecond) % m
        if (v2 > ans) ans = v2
    }
