import java.io.DataInputStream

class FastReader(stream: java.io.InputStream) {
    private val BUFSZ = 1 shl 16
    private val din = DataInputStream(stream)
    private val buffer = ByteArray(BUFSZ)
    private var bufferPointer = 0
    private var bytesRead = 0

    private fun read(): Byte {
        if (bufferPointer == bytesRead) fillBuffer()
        return buffer[bufferPointer++]
    }

    private fun fillBuffer() {
        bytesRead = din.read(buffer, 0, BUFSZ)
        bufferPointer = 0
        if (bytesRead == -1) { bytesRead = 0; buffer[0] = -1 }
    }

    fun nextInt(): Int {
        var ret = 0
        var b = read()
        while (b <= ' '.code.toByte()) b = read()
        val neg = b == '-'.code.toByte()
        if (neg) b = read()
        while (b >= '0'.code.toByte() && b <= '9'.code.toByte()) {
            ret = ret * 10 + (b - '0'.code.toByte())
            b = read()
        }
        return if (neg) -ret else ret
    }
}

fun main() {
    val fr = FastReader(System.`in`)
    val n = fr.nextInt()
    val m = fr.nextInt()
    val f = IntArray(n + 1)
    for (i in 1..n) f[i] = fr.nextInt()
    val ea = IntArray(m)
    val eb = IntArray(m)
    val outDeg = IntArray(n + 2)
    val inDeg = IntArray(n + 2)
    for (i in 0 until m) {
        val a = fr.nextInt()
        val b = fr.nextInt()
        ea[i] = a; eb[i] = b
        outDeg[a]++
        inDeg[b]++
    }
    val fStart = IntArray(n + 2)
    val rStart = IntArray(n + 2)
    for (i in 1..n) {
        fStart[i + 1] = fStart[i] + outDeg[i]
        rStart[i + 1] = rStart[i] + inDeg[i]
    }
    val fPos = IntArray(n + 2)
    val rPos = IntArray(n + 2)
    for (i in 1..n + 1) { fPos[i] = fStart[i]; rPos[i] = rStart[i] }
    val fAdj = IntArray(m)
    val rAdj = IntArray(m)
    for (i in 0 until m) {
        fAdj[fPos[ea[i]]++] = eb[i]
        rAdj[rPos[eb[i]]++] = ea[i]
    }

    val A = BooleanArray(n + 1)
    val B = BooleanArray(n + 1)
    val queue = IntArray(n + 1)

    var head = 0
    var tail = 0
    for (i in 1..n) if (f[i] == 1) { A[i] = true; queue[tail++] = i }
    while (head < tail) {
        val u = queue[head++]
        var j = fStart[u]
        val end = fStart[u + 1]
        while (j < end) {
            val w = fAdj[j]
            if (!A[w] && f[w] != 1) { A[w] = true; queue[tail++] = w }
            j++
        }
    }

    head = 0; tail = 0
    for (i in 1..n) if (f[i] == 2) { B[i] = true; queue[tail++] = i }
    while (head < tail) {
        val v = queue[head++]
        if (f[v] == 1) continue
        var j = rStart[v]
        val end = rStart[v + 1]
        while (j < end) {
            val u = rAdj[j]
            if (!B[u]) { B[u] = true; queue[tail++] = u }
            j++
        }
    }

    val sb = StringBuilder()
    for (i in 1..n) {
        sb.append(if (A[i] && B[i]) '1' else '0')
        sb.append('\n')
    }
    print(sb)
}
