const val INF = Long.MAX_VALUE / 4

fun mul(x: Array<LongArray>, y: Array<LongArray>, sz: Int): Array<LongArray> {
    val r = Array(sz) { LongArray(sz) { INF } }
    for (i in 0 until sz) {
        for (k in 0 until sz) {
            val v = x[i][k]
            if (v >= INF) continue
            val row = y[k]
            for (j in 0 until sz) {
                if (row[j] >= INF) continue
                val c = v + row[j]
                if (c < r[i][j]) r[i][j] = c
            }
        }
    }
    return r
}

fun main() {
    val st = StreamTokenizer(BufferedInputStream(System.`in`))
