    val base = Array(sz) { LongArray(sz) { INF } }
    for (s in 0 until sz) {
        var dp = LongArray(sz) { INF }
        dp[s] = 0
        for (p in 0 until n) {
            val nd = LongArray(sz) { INF }
            for (bal in 0 until sz) {
                if (dp[bal] >= INF) continue
                if (bal + 1 < sz) {
                    val c = dp[bal] + a[p]
                    if (c < nd[bal + 1]) nd[bal + 1] = c
                }
                if (bal - 1 >= 0) {
                    val c = dp[bal] + b[p]
                    if (c < nd[bal - 1]) nd[bal - 1] = c
                }
            }
            dp = nd
        }
        base[s] = dp
    }
    var result = Array(sz) { i -> LongArray(sz) { j -> if (i == j) 0L else INF } }
    var p = base
    var e = m
    while (e > 0) {
        if (e and 1 == 1) result = mul(result, p, sz)
        p = mul(p, p, sz)
        e = e shr 1
    }
    println(result[0][0])
}
