import java.util.Scanner

fun main() {
    val sc = Scanner(System.`in`)
    var n = sc.nextInt()
    var m = sc.nextInt()
    if (m > n) { val t = n; n = m; m = t }
    val full = (1 shl m) - 1
    val size = 1 shl m
    val INF = Int.MAX_VALUE / 2

    fun spread(s: Int): Int = ((s shl 1) or (s shr 1) or s) and full

    var dp = Array(size) { IntArray(size) { INF } }
    for (s in 0..full) {
        val c = spread(s)
        val cost = Integer.bitCount(s)
        if (cost < dp[s][c]) dp[s][c] = cost
    }

    for (row in 1 until n) {
        val ndp = Array(size) { IntArray(size) { INF } }
        for (s in 0..full) {
            for (cov in 0..full) {
                val cur = dp[s][cov]
                if (cur >= INF) continue
                for (s2 in 0..full) {
                    if ((cov or s2) != full) continue
                    val ncov = spread(s2) or s
                    val nc = cur + Integer.bitCount(s2)
                    if (nc < ndp[s2][ncov]) ndp[s2][ncov] = nc
                }
            }
        }
        dp = ndp
    }

    var best = INF
    for (s in 0..full) {
        if (dp[s][full] < best) best = dp[s][full]
    }
    println(n * m - best)
}
